19	int main(int argc, char* argv[]) {
20	    if (argc == 2 && std::string_view(argv[1]) == "--version") {
21	        std::cout << "branchaudit 0.1.0\n";
22	        return 0;
23	    }
24	
25	    if (argc >= 2 && std::string_view(argv[1]) == "hash") {
26	        // hash 恰好接受一个文件；缺失或多给都属于用法错误。
27	        if (argc != 3) {
28	            print_usage();
29	            return 2;
30	        }
31	        const branchaudit::FileHashResult result =
32	            branchaudit::sha256_file(argv[2]);
33	        if (!result.ok()) {
34	            std::cerr << "branchaudit: " << result.error << '\n';
35	            return 1;
36	        }
37	        std::cout << branchaudit::to_hex(result.digest) << '\n';
38	        return 0;
39	    }
40	
41	    if (argc >= 2 && std::string_view(argv[1]) == "root") {
42	        // root 接受零个或多个文件，顺序即命令行参数顺序：不排序、不去重。
43	        std::vector<std::filesystem::path> paths;
