#include <filesystem>
#include <iostream>
#include <string_view>
#include <vector>

#include "filehash.h"
#include "merkle.h"

namespace {

void print_usage() {
    std::cerr << "Usage: branchaudit --version\n"
                 "       branchaudit hash <file>\n"
                 "       branchaudit root [<file>...]\n";
}

}  // namespace

int main(int argc, char* argv[]) {
    if (argc == 2 && std::string_view(argv[1]) == "--version") {
        std::cout << "branchaudit 0.1.0\n";
        return 0;
    }

    if (argc >= 2 && std::string_view(argv[1]) == "hash") {
        // hash 恰好接受一个文件；缺失或多给都属于用法错误。
        if (argc != 3) {
            print_usage();
            return 2;
        }
        const branchaudit::FileHashResult result =
            branchaudit::sha256_file(argv[2]);
        if (!result.ok()) {
            std::cerr << "branchaudit: " << result.error << '\n';
            return 1;
        }
        std::cout << branchaudit::to_hex(result.digest) << '\n';
        return 0;
    }

    if (argc >= 2 && std::string_view(argv[1]) == "root") {
        // root 接受零个或多个文件，顺序即命令行参数顺序：不排序、不去重。
        std::vector<std::filesystem::path> paths;
        paths.reserve(static_cast<std::size_t>(argc - 2));
        for (int i = 2; i < argc; ++i) {
            paths.emplace_back(argv[i]);
        }
        const branchaudit::FileHashResult result =
            branchaudit::merkle_root_files(paths);
        if (!result.ok()) {
            std::cerr << "branchaudit: " << result.error << '\n';
            return 1;
        }
        std::cout << branchaudit::to_hex(result.digest) << '\n';
        return 0;
    }

    print_usage();
    return 2;
}

#pragma once

// branchaudit 内部共享头（非公开 API）：普通文件摘要（hash）与 Merkle 文件
// 叶子（root）通过这里共用同一套文件定位、打开、流式分块读取与读取失败
// 处理，保证两种计算对同一文件遵守一致规则，也避免同一种文件错误需要在
// 两处分别维护。对外公开的参数、结果类型与头文件仍保持 filehash.h /
// merkle.h 中已有的形态不变。

#include "filehash.h"

namespace branchaudit::internal {

// 流式计算 path 所指文件的 SHA-256 摘要。
//
// prefix_byte == nullptr：只对文件的全部原始字节计算标准 SHA-256（hash）。
// prefix_byte 指向单个字节：该字节在任何文件字节之前恰好参与一次摘要
// （Merkle 叶子的 0x00 前缀）——即使文件为空它也存在，且不会随读取分块
// 重复加入。两种情况下都只对实际读取到的字节计算：不包含路径文字，不做
// 编码转换、换行替换或空白处理。
//
// 路径不存在、指向目录、无法打开或中途读取失败时，返回 error 非空的结果，
// 已读到的部分内容不会成为成功结果。固定缓冲流式读取，内存占用与文件长度无关。
FileHashResult sha256_file_digest(const std::filesystem::path& path,
                                  const unsigned char* prefix_byte);

}  // namespace branchaudit::internal

