// 与 pattern() 相同的确定性序列，但只按位置取一个小缓冲内循环生成，
// 不按消息长度分配内存；供 512 MiB 级输入使用，保证测试自身内存有界。
unsigned char pattern_at(std::size_t i) {
    return static_cast<unsigned char>((i * 31 + 7) % 256);
}

// 固定大小的 pattern 缓冲：内容随全局位置变化，因此每一段都不一样，
// 既能发现段丢失/重复，也不按消息总长度分配内存。
std::vector<unsigned char> pattern_window(std::size_t offset, std::size_t len) {
    std::vector<unsigned char> v(len);
    for (std::size_t k = 0; k < len; ++k) v[k] = pattern_at(offset + k);
    return v;
}

// 以固定大小缓冲逐段向 Sha256 喂入 n 字节的 pattern 序列；缓冲长度与
// 消息总长度无关，内存占用有界。cut 为绝对字节偏移时，在该点前后各切
// 一刀（用更小的提交跨过该位置），用于让边界附近落在不同的 update 段内。
std::string hash_streaming_pattern(std::size_t n, std::size_t cut) {
    branchaudit::Sha256 sha;
    std::vector<unsigned char> window(kStreamChunk);
    std::size_t off = 0;
    // cut 附近的提交粒度（必须为 64 的约数之外的任意值即可，这里取质数值），
    // 让切分点不与 SHA-256 的 64 字节分组对齐。
    constexpr std::size_t kFine = 1009;
    while (off < n) {
        std::size_t len = kStreamChunk;
        if (off + len > n) len = n - off;
        // 若本段覆盖 cut，则在 cut 前 kFine/后 kFine 处拆成三次提交。
        if (cut > off && cut < off + len) {
            const std::size_t local = cut - off;
            const std::size_t before = local > kFine ? local - kFine : 0;
            const std::size_t span_start = before;
            const std::size_t span_end =
                local + kFine < len ? local + kFine : len;
            if (span_start > 0) {
                for (std::size_t k = 0; k < span_start; ++k)
                    window[k] = pattern_at(off + k);
                sha.update(window.data(), span_start);
            }
            // [span_start, cut) 与 (cut, span_end)：逐字节切，cut 单独一段，
            // 保证边界两侧绝不在同一次 update 中。
            for (std::size_t k = span_start; k < span_end; ++k) {
                unsigned char one = pattern_at(off + k);
                sha.update(&one, 1);
            }
            if (span_end < len) {
                for (std::size_t k = span_end; k < len; ++k)
                    window[k - span_end] = pattern_at(off + k);
                sha.update(window.data(), len - span_end);
            }
        } else {
            for (std::size_t k = 0; k < len; ++k)
                window[k] = pattern_at(off + k);
            sha.update(window.data(), len);
        }
        off += len;
    }
    return hex_of(sha.final());
}

// 以两种不同分段策略流式喂入同一 pattern：常规 1 MiB 大块，与在 cut 附近
// 逐字节拆开。两者都不按消息总长度分配内存。
std::string hash_streaming_whole(std::size_t n) {
    return hash_streaming_pattern(n, n + 1);  // cut 落在消息外：不触发细切
}

void expect_digest(std::string_view label, const std::vector<unsigned char>& data,
                   std::string_view expected) {
    check(hash_whole(data) == expected, label);
}

